responses.text:
{
  "outcome": "revise",
  "issues": [
    {
      "kind": "contradiction",
      "severity": "critical",
      "description": "승인된 기술 제약인 '알 수 없는 스키마 버전은 원본 보존과 쓰기 차단으로 처리한다'와 정면으로 배치되게, 10번 줄에서 모르는 version을 읽었을 때 items를 빈 배열로 바꾸어 version 1로 덮어쓰도록 명시되어 있어 영속 데이터가 손실됩니다.",
      "suggestedDirection": "알 수 없는 스키마 버전을 만났을 때 데이터를 덮어쓰지 않고, 다른 스키마 위반과 동일하게 원본 데이터를 보존한 채 신규 쓰기를 차단하도록 계획을 수정해야 합니다.",
      "relatedRequirementId": "R-3"
    }
  ],
  "suggestions": [
    "10번 줄의 '모르는 version을 읽으면 호환을 위해 items를 빈 배열로 바꿔 version1로 덮어쓴다' 문구를 삭제하고 승인된 제약대로 원본 보존 및 쓰기 차단으로 일원화하십시오."
  ],
  "scopeViolation": true,
  "userJudgmentRequired": false,
  "qualityAssessment": {
    "version": 1,
    "requirements": [
      {
        "requirementId": "R-1",
        "status": "satisfied",
        "evidenceLines": [3, 4, 8],
        "rationale": "물건명과 사람명 입력 및 동일 물건명의 별개 등록이 구체적으로 명시되어 있습니다."
      },
      {
        "requirementId": "R-2",
        "status": "satisfied",
        "evidenceLines": [5, 9],
        "rationale": "선택된 단일 ID에 한해 반환 상태로 변경하며 타 항목에 영향을 주지 않도록 정의되어 있습니다."
      },
      {
        "requirementId": "R-3",
        "status": "missing",
        "evidenceLines": [6, 10],
        "rationale": "모르는 스키마 버전을 빈 배열로 덮어쓰도록 규정하여 잘못된/알 수 없는 저장 데이터 원본을 보존해야 하는 요구사항 및 제약과 모순됩니다."
      }
    ],
    "checks": [
      {
        "id": "decision_provenance",
        "status": "satisfied",
        "evidenceLines": [12],
        "rationale": "키 이름 및 데이터 표현을 위임된 설계 제안으로 명확히 구분하고 사용자 결정으로 사칭하지 않았습니다."
      },
      {
        "id": "scope_compliance",
        "status": "missing",
        "evidenceLines": [10],
        "rationale": "승인된 기술 제약인 '알 수 없는 스키마 버전의 원본 보존 및 쓰기 차단'을 위반하고 데이터를 덮어쓰도록 작성되었습니다."
      },
      {
        "id": "behavior_and_errors",
        "status": "missing",
        "evidenceLines": [10],
        "rationale": "스키마 위반 시 원본 보존/쓰기 차단 규칙과 모르는 버전 덮어쓰기 규칙이 상충되어 오류 처리 동작이 모순됩니다."
      },
      {
        "id": "data_integrity",
        "status": "missing",
        "evidenceLines": [10],
        "rationale": "알 수 없는 버전에 대한 덮어쓰기 동작으로 인해 영속 데이터의 임의 소실이 발생합니다."
      },
      {
        "id": "acceptance_criteria",
        "status": "satisfied",
        "evidenceLines": [8, 9, 10],
        "rationale": "각 요구사항별 구체적인 입력 조건과 기대 결과가 명시되어 있습니다."
      },
      {
        "id": "revision_resolution",
        "status": "not_applicable",
        "evidenceLines": [13],
        "rationale": "settledDecisions가 비어 있으며 이전 수정 요청이 없는 신규 기획안입니다."
      },
      {
        "id": "clarity",
        "status": "satisfied",
        "evidenceLines": [2, 3, 4, 5, 6, 7],
        "rationale": "쉬운 한국어 이용 예시를 앞단에 먼저 배치하고 상세 기술 사양을 뒤로 분리했습니다."
      }
    ]
  }
}
